const target = { 
  secret: 'shhh',
  public: 'hello'
};

const handler = {
  // 1. Trap that intercepts read (Get) operations
  get(obj, prop) {
    if (prop === 'secret') {
      return 'Access Denied!';
    }
    // 2. Forward the rest to the original object (Forwarding)
    return Reflect.get(obj, prop);
  }
};

// Creating a Proxy that wraps the original (Target)
const proxy = new Proxy(target, handler);

console.log(proxy.public); // hello
console.log(proxy.secret); // Access Denied!
